import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a valid draft invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2024-01-15');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 2);
});

test('createInvoice enriches lines with catalogue data', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  const line = result.value.lines[0];
  assert.equal(line.sku, 'DEV-HOUR');
  assert.equal(line.name, 'Development (hour)');
  assert.equal(line.qty, 5);
  assert.equal(line.unitPrice, 9500);
  assert.equal(line.vatRate, 21);
});

test('createInvoice fails with CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice fails with DATE_INVALID for bad date format', () => {
  const cases = [
    '2024-1-15',
    '2024/01/15',
    '01-15-2024',
    'invalid',
    '',
    '2024-13-01',
    '2024-02-30',
    '2024-00-01',
    '2024-01-00',
  ];

  for (const issueDate of cases) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate,
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    });
    assert.equal(result.ok, false, `Should fail for ${issueDate}`);
    assert.equal(result.error, 'DATE_INVALID', `Should fail with DATE_INVALID for ${issueDate}`);
  }
});

test('createInvoice fails with NO_LINES for empty lines array', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [],
  });

  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('createInvoice fails with QTY_INVALID for invalid quantities', () => {
  const cases = [0, -1, -10, 1.5, 10.5, NaN, Infinity, null, undefined, '5'];

  for (const qty of cases) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'DEV-HOUR', qty }],
    });
    assert.equal(result.ok, false, `Should fail for qty ${qty}`);
    assert.equal(result.error, 'QTY_INVALID', `Should fail with QTY_INVALID for qty ${qty}`);
  }
});

test('createInvoice fails with UNKNOWN_SKU for unknown product', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'UNKNOWN-PRODUCT', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice handles multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-06-20',
    lines: [
      { sku: 'DES-HOUR', qty: 8 },
      { sku: 'DEV-HOUR', qty: 16 },
      { sku: 'PRINT-A4', qty: 500 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 3);
  assert.equal(result.value.lines[0].name, 'Design work (hour)');
  assert.equal(result.value.lines[1].name, 'Development (hour)');
  assert.equal(result.value.lines[2].name, 'Printed flyer A4 (each)');
});

test('createInvoice does not mutate input', () => {
  const lines = [{ sku: 'DEV-HOUR', qty: 1 }];
  const originalLines = JSON.parse(JSON.stringify(lines));

  createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines,
  });

  assert.deepEqual(lines, originalLines);
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 10, unitPrice: 9500 }), 95000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 500, unitPrice: 37 }), 18500);
});

test('lineTotal works with qty 1', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 8500 }), 8500);
});

test('invoiceTotals sums all line totals', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 10 * 9500 + 5 * 8500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, totals.subtotal);
});

test('invoiceTotals returns equal subtotal and total when no discount', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2024-01-15',
    lines: [{ sku: 'ICON-SET', qty: 100 }],
  });

  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, totals.total);
});

test('invoiceTotals with single line', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2024-01-15',
    lines: [{ sku: 'BRAND-BOOK', qty: 2 }],
  });

  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 2 * 245000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 2 * 245000);
});

test('createInvoice accepts discountPercent on lines', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'ICON-SET', qty: 100, discountPercent: 0 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 10);
  assert.equal(result.value.lines[1].discountPercent, undefined);
});

test('createInvoice rejects invalid discountPercent', () => {
  const cases = [
    { sku: 'DEV-HOUR', qty: 1, discountPercent: -1 },
    { sku: 'DEV-HOUR', qty: 1, discountPercent: 101 },
    { sku: 'DEV-HOUR', qty: 1, discountPercent: 'invalid' },
    { sku: 'DEV-HOUR', qty: 1, discountPercent: NaN },
  ];

  for (const line of cases) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [line],
    });
    assert.equal(result.ok, false, `Should fail for discountPercent ${line.discountPercent}`);
    assert.equal(result.error, 'DISCOUNT_INVALID');
  }
});

test('createInvoice allows omitting discountPercent (applies tier discount)', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, undefined); // standard = 0%
});

test('createInvoice accepts decimal discount percentages', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 12.5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 12.5);
});

test('createInvoice applies gold tier discount (5%) when no discount specified', () => {
  const result = createInvoice({
    customerId: 'C-001', // Northwind Studio, gold tier
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 5);
});

test('createInvoice applies silver tier discount (2.5%) when no discount specified', () => {
  const result = createInvoice({
    customerId: 'C-003', // Kite & Co, silver tier
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 2.5);
});

test('createInvoice applies standard tier discount (0%) when no discount specified', () => {
  const result = createInvoice({
    customerId: 'C-002', // Blue Fern Bakery, standard tier
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, undefined);
});

test('createInvoice explicit discount (0) overrides tier discount', () => {
  const result = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, undefined);
});

test('createInvoice explicit discount overrides tier discount', () => {
  const result = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 20 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 20);
});

test('createInvoice applies tier discount per customer for multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'ICON-SET', qty: 100 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 5); // gold tier
  assert.equal(result.value.lines[1].discountPercent, 10); // explicit
  assert.equal(result.value.lines[2].discountPercent, 5); // gold tier
});

test('addLine adds a new line to an invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const result = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });

  assert.equal(result.ok, true);
