  assert.deepEqual(lines, originalLines);
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 10, unitPrice: 9500 }), 95000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 500, unitPrice: 37 }), 18500);
});

test('lineTotal works with qty 1', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 8500 }), 8500);
});

test('lineDiscount calculates discount on line total', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 9500, discountPercent: 10 }), 9500);
  assert.equal(lineDiscount({ qty: 10, unitPrice: 9500, discountPercent: 0 }), 0);
  assert.equal(lineDiscount({ qty: 10, unitPrice: 9500 }), 0); // undefined = 0%
});

test('lineVAT calculates VAT on amount after discount', () => {
  // 10 × 9500 = 95000
  // No discount
  // 21% VAT = 19950
  const line1 = { qty: 10, unitPrice: 9500, vatRate: 21 };
  assert.equal(lineVAT(line1), 19950);

  // 10 × 9500 = 95000, 10% discount = 9500
  // After discount: 85500
  // 21% VAT = 17955
  const line2 = { qty: 10, unitPrice: 9500, vatRate: 21, discountPercent: 10 };
  assert.equal(lineVAT(line2), 17955);

  // 0% VAT
  const line3 = { qty: 10, unitPrice: 9500, vatRate: 0 };
  assert.equal(lineVAT(line3), 0);
});

test('lineVAT with different VAT rates', () => {
  // 9% VAT
  const line9 = { qty: 100, unitPrice: 37, vatRate: 9 };
  assert.equal(lineVAT(line9), 333); // 3700 × 9% = 333

  // 21% VAT
  const line21 = { qty: 100, unitPrice: 980, vatRate: 21 };
  assert.equal(lineVAT(line21), 20580); // 98000 × 21% = 20580
});

