  const totals = invoiceTotals(result.value);

  // Line 1: 5 × 9500 = 47500, 0% = 0
  // Line 2: 5 × 8500 = 42500, 50% = 21250
  // Subtotal = 90000, Discount = 21250, Total = 68750
  assert.equal(totals.subtotal, 90000);
  assert.equal(totals.discount, 21250);
  assert.equal(totals.total, 68750);
});

test('invoiceTotals includes VAT calculation', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const totals = invoiceTotals(result.value);

  // 10 × 9500 = 95000 (subtotal)
  // No discount
  // 21% VAT on 95000 = 19950
  // Total = 95000 + 19950 = 114950
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 19950);
  assert.equal(totals.total, 114950);
});

test('invoiceTotals calculates VAT after discount', () => {
  const result = createInvoice({
    customerId: 'C-001', // gold tier, 5%
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const totals = invoiceTotals(result.value);

  // 10 × 9500 = 95000
  // 5% discount = 4750
  // After discount = 90250
  // 21% VAT on 90250 = 18952.5 → 18953 (rounded)
  // Total = 95000 - 4750 + 18953 = 109203
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.vat, 18953);
  assert.equal(totals.total, 109203);
});

